INSERT INTO arms_skills (armsid, kind, jobid, skillid, name, description, ap, cp, damage, seq) VALUES
  ('ARM100101', '其他', 0, 'SS100101', '前线目光', '攻击前方1格内1个地面目标。若本次攻击造成目标【减员】，则我方所有红十月学联地面单位【对地火力】提升15%，持续1回合。', 1, 3, 100, 0),
  ('ARM100101', '其他', 0, 'DOL1001', '崇高使命', '自身【伤害豁免】提升15%。自身受到攻击后，【对地火力】提升16%，持续整场战斗，每场战斗可以生效三次。', 0, 0, 0, 1),
  ('ARM100101', '其他', 0, 'AS1037', '洞若观火', '受到攻击时，如攻击者是【被标记】的目标，该目标的【对地命中补正】降低5%。', 0, 0, 0, 2),
  ('ARM100101', '其他', 0, 'AS2031', '重装上阵', '我方阶段开始时，若场上存在≥3个我方重型单位，则本回合自身【贯通】提升5%，【暴击概率】提升9%。', 0, 0, 0, 3),
  ('ARM100101', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM100101', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM100101', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM100101', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM100101', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM100101', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM100101', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM100101', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM100102', '其他', 0, 'SS100102', '前线目光·改', '强力攻击前方1格内1个地面目标。若本次攻击造成目标【减员】，则我方所有红十月学联地面单位【对地火力】提升15%，持续1回合。', 1, 5, 150, 0),
