  ('ARM101202', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM101203', '其他', 0, 'SS101203', '联邦骑炮兵', '对射程内所有地面目标进行强力攻击，仅在移动形态下可用。', 1, 8, 125, 0),
  ('ARM101203', '其他', 0, 'DOL1012', '先锋特遣队', '我方阶段开始时，赋予自身前方1-4格范围1个敌方地面目标特殊标记【就是这家伙】，持续3回合。且全体星尘联邦学联地面重型单位本回合【暴击伤害】提升26%，【暴击概率】提升15%。', 0, 0, 0, 1),
  ('ARM101203', '其他', 0, 'AS1022', '集群效益（陆）·改', '主动攻击地面目标时，若自身【成员数】＞2，则自身【对地火力】提升8%；若自身【成员数】＞5，则【对地火力】额外提升3%；若自身【成员数】＞7，则【对地火力】再额外提升4%。', 0, 0, 0, 2),
  ('ARM101203', '其他', 0, 'AS2018', '前线联络·改', '自身主动攻击前，若目标前方1格范围内存在与其同位面的我方单位，则本回合自身【命中】提升14%，【暴击概率】提升20%。', 0, 0, 0, 3),
  ('ARM101203', '职能', 5, 'SJ0521', '隐匿埋伏', '清除自身所有【标记】，自身【暴击概率】提升28%，【存在感】降低2点，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 0),
  ('ARM101203', '职能', 5, 'SJ0522', '隐匿狙击', '攻击前方1个【被标记】敌人，本次攻击【对地火力】提升30%，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 2, 3, 100, 1),
  ('ARM101203', '职能', 5, 'SJ0523', '坚守警戒', '本回合内，对自身前方地面1-4格范围内所有移动过的敌人发动警戒攻击，若敌方目标【被标记】，则攻击前自身【对地火力】提升24%，本次警戒攻击有效。', 2, 5, 0, 2),
  ('ARM101203', '职能', 5, 'SJ0524', '移动射击', '攻击前方地面1-1格范围内1个敌人1次，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 1, 0, 100, 3),
