  ('ARM102101', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM102102', '其他', 0, 'SS102102', '动力超频·改', '自身进入【超频】状态——【机动】和【贯通】提升15%，【暴击伤害】和【威力】提升40%，持续2回合。在【超频】状态下主动攻击后将赋予自身【禁锢】，持续1回合。', 1, 3, 0, 0),
  ('ARM102102', '其他', 0, 'DOL1021', '哈米尔卡伞兵', '自身行动前，场上每存在1个带有【标记】的敌方地面单位，自身【对地火力】提升14%，最高可提升42%，本回合有效。', 0, 0, 0, 1),
  ('ARM102102', '其他', 0, 'AS1036', '危机应对（陆）·改', '我方阶段开始时，若自身前方1~2格存在敌方地面单位，则自身【反应值】提升11点，【装甲】提升28%，持续1回合（不可叠加）。', 0, 0, 0, 2),
  ('ARM102102', '其他', 0, 'AS1138', '平顺转向·改', '自身行动前，自身【机动】随本回合移动距离提升，每移动1格【机动】提升7%，最高可提升28%，持续1回合，不可叠加。', 0, 0, 0, 3),
