  ('ARM102502', '职能', 1, 'SJ0121', '游击侦察', '攻击自身前方地面1-2格范围内1个敌人并【标记】，持续3回合。攻击后自身后退1格。', 2, 0, 100, 0),
  ('ARM102502', '职能', 1, 'SJ0122', '隐匿', '使自身进入固守形态，清除自身所有【标记】，自身【存在感】降低2点，【暴击概率】提升28%，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 1),
  ('ARM102502', '职能', 1, 'SJ0123', '定点侦察', '敌方阶段时，自身前方地面1-4格范围内敌人在攻击前将会赋予【被标记】，持续3回合，且其【命中补正】降低20%，持续1回合。', 2, 5, 0, 2),
  ('ARM102502', '职能', 1, 'SJ0125', '奇袭白刃', '对自身前方1个带有【标记】的敌人发动白刃战。', 2, 5, 100, 3),
  ('ARM102502', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM102502', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM102502', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM102502', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM102502', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM102502', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM102502', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM102502', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM102701', '其他', 0, 'SS102701', '看这边！', '强力攻击前方1~2格1个敌方地面单位，攻击后赋予目标【被嘲讽·陆】和【标记】状态，持续1回合。被嘲讽·陆：主动攻击我方地面单位时攻击目标被强制变更为此状态的施加者（不可叠加）。', 1, 8, 150, 0),
  ('ARM102701', '其他', 0, 'DOL1027', '“计划通”', '所有我方红十月单位【伤害】永久提升12%。我方单位行动后，若其本回合发动过主动攻击，则使特殊个体以外的敌方地面单位【存在感】降低3点，持续1回合（不可叠加），并使敌方地面特殊个体获得1层【左支右绌】，持续1回合。左支右绌：T-126/T-50主动攻击时，目标每有1层左支右绌本次攻击【暴击概率】【暴击伤害】【贯通】提升15%（最高75%）。', 0, 0, 0, 1),
  ('ARM102701', '其他', 0, 'AS2133', '贴身护卫', '自身【存在感】永久提升4点。我方阶段开始时，同格每存在1个我方地面单位，本回合自身【装甲】【机动】提升3%。', 0, 0, 0, 2),
