  ('ARM103501', '其他', 0, 'AS2107', '边疆守卫者', '我方阶段开始时，若自身前方不存在我方地面单位且自身处于固守形态，则本回合自身【暴击概率】提升40%，同格和身后1格的其他我方地面单位【暴击概率】提升8%。', 0, 0, 0, 3),
  ('ARM103501', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
