  ('ARM103502', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM103502', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM103502', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM103502', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM103502', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM103502', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM103502', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM103502', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM103502', '职能', 6, 'SJ0622', '机动支援', '自身进入固守形态，攻击自身前方地面1-2的1个敌人1次，并【标记】目标，持续3回合。', 2, 3, 100, 0),
  ('ARM103502', '职能', 6, 'SJ0623', '火力支援', '攻击前方1个地面【被标记】的敌人，并【标记】自身2回合。自身攻击前，自身【对地火力】提升30%，本次攻击有效。', 2, 3, 100, 1),
  ('ARM103502', '职能', 6, 'SJ0624', '火力掩护', '本回合可对前方1-4格范围内所有主动攻击过的敌人发动反击。', 2, 5, 0, 2),
  ('ARM103701', '其他', 0, 'SS103701', '集群之力', '固守形态限定。对场上所有被【标记】的敌方地面单位发动2次攻击。', 2, 5, 75, 0),
  ('ARM103701', '其他', 0, 'DOL1037', '复仇之锤', '己方单位受到攻击时，自身【对地火力】提升10%，【暴击概率】提升15%，持续1回合。', 0, 0, 0, 1),
  ('ARM103701', '其他', 0, 'AS2017', '前线联络', '自身主动攻击前，若目标前方1格范围内存在与其同位面的我方单位，则本回合自身【命中】提升5%，【暴击概率】提升9%。', 0, 0, 0, 2),
  ('ARM103701', '其他', 0, 'AS2037', '稳固阵型', '主动攻击时，若自身-1到1格范围不存在其他我方地面单位，且自身前方＞1格范围存在我方地面单位，则自身【火力】提升5%。', 0, 0, 0, 3),
  ('ARM103701', '职能', 5, 'SJ0521', '隐匿埋伏', '清除自身所有【标记】，自身【暴击概率】提升28%，【存在感】降低2点，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 0),
