  ('ARM104301', '职能', 6, 'SJ0624', '火力掩护', '本回合可对前方1-4格范围内所有主动攻击过的敌人发动反击。', 2, 5, 0, 2),
  ('ARM104302', '其他', 0, 'SS104302', '要有光', '固守形态技能。以1%威力攻击前方3~4格所有敌方地面单位并驱散所有敌方地面单位【隐匿】状态，赋予所有敌方地面单位【暴露】状态，持续1回合（不可叠加）。若目标已处于【暴露】则本次攻击威力提升74%。【暴露】：无法进入【隐匿】状态；我方单位主动攻击【暴露】状态的目标时【命中】【贯通】【暴击概率】提升15%。', 1, 8, 1, 0),
  ('ARM104302', '其他', 0, 'DOL1043', '坚振', '首个我方阶段开始时，场上每存在1个其他我方星尘或白蔷薇火炮单位，自身【暴击伤害】永久提升20%。自身主动攻击【暴露】状态的目标时【伤害】提升170%。', 0, 0, 0, 1),
  ('ARM104302', '其他', 0, 'AS2042', '空中联络·改', '主动攻击敌方地面单位时，若目标同格存在我方空中单位，则本次攻击【对地命中补正】提升10%，【暴击概率】提升20%。', 0, 0, 0, 2),
  ('ARM104302', '其他', 0, 'AS2096', '情报搜集', '自身行动前，场上每存在1个被【标记】的敌方单位，本回合自身【暴击概率】和【暴击伤害】提升10%，最高可提升60%。', 0, 0, 0, 3),
  ('ARM104302', '职能', 7, 'SJ0721', '预先装填', '切换为固守形态。若前方第2格存在敌方地面单位，则自身【命中】与【贯通】提升16%，持续2回合，不可叠加。下回合主动攻击后，对攻击范围内离自身最近的1格内地面目标发动1次追击。', 1, 3, 0, 0),
  ('ARM104302', '职能', 7, 'SJ0722', '徐进弹幕', '对所有【被标记】地面敌方单位发动1次攻击。自身攻击前，自身【对地火力】提升15%，本次攻击有效。', 1, 3, 75, 1),
