  ('ARM105702', '其他', 0, 'DOL1057', 'Бойся меня！', '自身行动前，若本回合自身前进过则所有我方红十月单位【火力】提升20%，持续1回合（不可叠加）。我方红十月单位行动后，若其本回合前进过，则其【机动】与【装甲】永久提升15%，整场战斗可生效2次。', 0, 0, 0, 1),
  ('ARM105702', '其他', 0, 'AS1094', '重装对决·改', '我方阶段开始时，若场上存在1/2/超过2个敌方重型单位，则自身【对地火力】提升13/26/40%，【贯通】提升16/18/21%，持续永久。整场战斗可生效1次。', 0, 0, 0, 2),
  ('ARM105702', '其他', 0, 'AS2064', '我们的近卫军·改', '我方阶段开始时，场上每存在1个我方红十月单位，则本回合自身【火力】提升10%（最高可提升40%）。', 0, 0, 0, 3),
  ('ARM105702', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM105702', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM105702', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM105702', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM105702', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
