  ('ARM106201', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM106201', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM106201', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
