  ('ARM107402', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM107402', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM107402', '职能', 1, 'SJ0121', '游击侦察', '攻击自身前方地面1-2格范围内1个敌人并【标记】，持续3回合。攻击后自身后退1格。', 2, 0, 100, 0),
