  ('ARM108102', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM108102', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM108102', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM108102', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM108102', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM108102', '职能', 4, 'SJ0421', '近距射击', '攻击前方1-1格范围内1个敌人1次，若目标【被标记】，本次攻击【对地火力】提升30%。', 1, 0, 100, 0),
  ('ARM108102', '职能', 4, 'SJ0422', '破阵猛击', '攻击前方2-3格范围内1个敌人，并赋予目标【破阵】状态，若目标【被标记】，可发动追击。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 2, 5, 100, 1),
  ('ARM108102', '职能', 4, 'SJ0423', '歼灭狙击', '攻击前方1个【被标记】的敌人，本次攻击【对地火力】提升30%。', 2, 3, 150, 2),
  ('ARM108201', '其他', 0, 'SS108201', '金刚不坏', '移动形态技能。自身前进1格；【伤害豁免】提升20%，持续4回合；【对地火力】提升20%，持续永久。攻击前方1~3格1个距离最近的敌方地面单位并将其击退1格。仅能在前4回合使用。', 3, 5, 100, 0),
  ('ARM108201', '其他', 0, 'SS108211', '智慧之剑', '固守形态技能。超强力攻击前方1~3格1个敌方地面单位，攻击后赋予目标【破阵】状态，持续永久，并【驱散】目标3个正面状态。破阵：【负面状态生效率】提升100%，处于破阵状态的单位行动后若处于固守形态则清除其自身破阵。', 1, 6, 200, 1),
  ('ARM108201', '其他', 0, 'DOL1082', '不动战姬', '我方阶段开始时，若本回合自身没有移动过，则本回合自身【对地火力】【伤害豁免】【装甲】提升20%，并【驱散】自身1个负面状态。', 0, 0, 0, 2),
  ('ARM108201', '其他', 0, 'AS2129', '无炮塔坦克', '自身主动攻击前，自身-2~2格每存在1个其他我方地面单位，本次攻击【暴击概率】提升7%。自身被前方1~3格地面单位白刃前对白刃者发动100%威力警戒攻击，每回合可生效1次。', 0, 0, 0, 3),
  ('ARM108201', '其他', 0, 'AS3061', '守护者', '自身【存在感】永久提升3点，【装甲】永久提升5%。自身主动攻击后，驱散自身0~-2格所有其他我方地面单位【标记】并赋予她们【隐匿Ⅱ】状态，本回合有效。隐匿Ⅱ：①广域攻击技能的目标中处于【隐匿Ⅱ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅱ】不对处于【标记】状态的目标生效。', 0, 0, 0, 4),
  ('ARM108201', '职能', 6, 'SJ0622', '机动支援', '自身进入固守形态，攻击自身前方地面1-2的1个敌人1次，并【标记】目标，持续3回合。', 2, 3, 100, 0),
  ('ARM108201', '职能', 6, 'SJ0623', '火力支援', '攻击前方1个地面【被标记】的敌人，并【标记】自身2回合。自身攻击前，自身【对地火力】提升30%，本次攻击有效。', 2, 3, 100, 1),
  ('ARM108201', '职能', 6, 'SJ0624', '火力掩护', '本回合可对前方1-4格范围内所有主动攻击过的敌人发动反击。', 2, 5, 0, 2),
  ('ARM108201', '职能', 5, 'SJ0521', '隐匿埋伏', '清除自身所有【标记】，自身【暴击概率】提升28%，【存在感】降低2点，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 0),
  ('ARM108201', '职能', 5, 'SJ0522', '隐匿狙击', '攻击前方1个【被标记】敌人，本次攻击【对地火力】提升30%，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 2, 3, 100, 1),
