  ('ARM109801', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM109802', '其他', 0, 'SS109802', '饿虎扑食', '固守形态技能。本回合自身【暴击率】【对地火力】提升32%，强力攻击前方1~2格1个敌方地面单位，攻击后若场上存在我方歼击车则再发动1次强力攻击。', 0, 5, 150, 0),
  ('ARM109802', '其他', 0, 'DOL1098', '一视同仁', '作战开始时，【暴击伤害】永久提升32%，且【装甲】永久提升，幅度=场上斐迪南/象式基础装甲值的40%。斐迪南/象式特性「梯次防御」警戒范围变更为前方3~4格地面。', 0, 0, 0, 1),
  ('ARM109802', '其他', 0, 'AS3078', 's.Pz.Jäg.Abt', '作战开始时，若场上存在≥2个我方重型歼击车单位，则赋予1个装甲最低的我方地面单位【隐匿Ⅱ】状态，持续永久，且所有我方重型歼击车【暴击概率】【暴击伤害】提升32%，【CP恢复】提升1点，持续永久（不可叠加）。隐匿Ⅱ：①广域攻击技能的目标中处于隐匿Ⅱ状态且存在感不是最高的目标不会受到攻击伤害；②隐匿Ⅱ不对处于标记状态的目标生效。', 0, 0, 0, 2),
  ('ARM109802', '其他', 0, 'AS3080', '一线指挥', '我方地面单位行动后，虎(P)【标记】自身前方1~2格1个敌方地面单位，持续1回合。敌方地面单位受主动攻击时，若该敌方单位处于移动形态，则其在本次攻击中【伤害豁免】降低24%（不可叠加）。', 0, 0, 0, 3),
  ('ARM109802', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM109802', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM109802', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM109802', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM109802', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM109802', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM109802', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM109802', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM109901', '其他', 0, 'SS109901', '堡垒行动', '固守形态限定。使前方所有我方坦克前进1格。攻击前方3-4格1个敌方地面单位，自身切换为移动形态。', 1, 5, 100, 0),
