  ('ARM110601', '其他', 0, 'DOL1106', '反射装甲', '【装甲】永久提升20%。受主动攻击后，对攻击者造成等于本次IS-3/704工程受到的潜在伤害×IS-3/704工程当前装甲值×2÷攻击者当前机动值的【燃烧】伤害（上限80000点）。潜在伤害：不计算暴击抗性、装甲、伤害豁免、普通/溅射伤害修正情况下的理论伤害量。', 0, 0, 0, 1),
  ('ARM110601', '其他', 0, 'AS3089', '缺陷修正', '施放「人人有责」后，若生命值＜初始生命值，【恢复】-1~1格所有我方地面单位IS-3当前装甲值20%的生命值，可生效10次；且-1~1格每存在1个我方地面单位，范围内我方地面单位承受「人人有责」转移的伤害量减少2%，可生效无限次。', 0, 0, 0, 2),
  ('ARM110601', '其他', 0, 'AS3091', '首要威胁', '其他我方地面单位【存在感】永久降低2点。所有我方和敌方单位主动攻击地面目标时【暴击概率】提升15%。', 0, 0, 0, 3),
  ('ARM110601', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM110601', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM110601', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM110601', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM110601', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM110601', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
