  ('ARM110801', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM110802', '其他', 0, 'SS110802', '地动山摇·改', '对前方1格的3个地面目标进行范围攻击。攻击后，对前方2格范围内的地面轻型与中型目标造成【禁锢】效果。持续1回合。', 1, 8, 125, 0),
  ('ARM110802', '其他', 0, 'DOL1108', '路上要塞', '我方阶段开始时，前方1格存在地面轻型或中型目标时，场上我方其他地面非重型单位存在感降低2。当自身在固守形态下受到主动攻击时，自身【装甲】提升20%，持续2回合。', 0, 0, 0, 1),
  ('ARM110802', '其他', 0, 'AS1036', '危机应对（陆）·改', '我方阶段开始时，若自身前方1~2格存在敌方地面单位，则自身【反应值】提升11点，【装甲】提升28%，持续1回合（不可叠加）。', 0, 0, 0, 2),
  ('ARM110802', '其他', 0, 'AS1062', '八百万神灵·改', '自身主动攻击前方1格的轻型或中型目标后，对其中1个目标发动150%威力追击。自身受前方1格轻型或中型地面单位主动攻击前，若自身处于固守形态，则对攻击者发动150%威力反击。可生效无限次。', 0, 0, 0, 3),
  ('ARM110802', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM110802', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM110802', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM110802', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM110802', '职能', 3, 'SJ0321', '佯攻', '赋予自身【标记】，自身【暴击概率】提升25%，【存在感】提升2，持续1回合。【伤害豁免】提升20%，本回合有效。攻击自身前方地面1-1格范围内1个敌人。', 1, 3, 100, 0),
  ('ARM110802', '职能', 3, 'SJ0322', '防卫警戒', '自身进入固守形态。敌方阶段，对前方1-2的1个敌人发动一次警戒攻击。', 1, 3, 0, 1),
  ('ARM110802', '职能', 3, 'SJ0324', '威慑射击', '攻击前方1-2格范围内1个敌人，攻击后自身【存在感】提升4，本回合有效。', 1, 3, 100, 2),
  ('ARM110802', '职能', 3, 'SJ0325', '反击阵地', '本回合可反击所有范围2以内攻击自己的敌方地面单位。赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，自身【装甲】提升50%，【伤害豁免】提升20%，本回合内有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】提升30%，持续3回合，不可叠加。回合开始时，若自身处于移动形态，则清除自身【阵地】状态。', 1, 5, 0, 3),
  ('ARM111701', '其他', 0, 'SS111701', '特大烟花', '固守形态限定。以165%威力攻击前方3~4格所有敌方地面单位。攻击后【哑火】自身1回合，并迫使前方第3格所有敌方地面单位前进1格，第4格所有敌方地面单位后退1格。再对仍留在突击虎前方3~4格的敌方地面单位造成等于突击虎当前单成员对地火力5倍的【燃烧】伤害。', 2, 8, 165, 0),
  ('ARM111701', '其他', 0, 'DOL1117', '夷为平地', '主动攻击前【驱散】所有敌方地面单位【存在感提升/降低】【隐匿】状态，并赋予所有敌方地面单位【暴露】状态，持续1回合（不可叠加），整场战斗可生效1次。主动攻击后使「虎式」本回合【威力】提升30%。敌方阶段开始时，「突击虎」本回合主动攻击过的目标获得【高威胁方位】状态，持续至下个我方阶段开始。【暴露】：无法进入【隐匿】状态；我方单位主动攻击【暴露】状态的目标时【命中】【贯通】【暴击概率】提升15%。【高威胁方位】：伤害豁免降低20%（不可叠加）。', 0, 0, 0, 1),
  ('ARM111701', '其他', 0, 'AS2017', '前线联络', '自身主动攻击前，若目标前方1格范围内存在与其同位面的我方单位，则本回合自身【命中】提升5%，【暴击概率】提升9%。', 0, 0, 0, 2),
  ('ARM111701', '其他', 0, 'AS2031', '重装上阵', '我方阶段开始时，若场上存在≥3个我方重型单位，则本回合自身【贯通】提升5%，【暴击概率】提升9%。', 0, 0, 0, 3),
  ('ARM111701', '职能', 7, 'SJ0721', '预先装填', '切换为固守形态。若前方第2格存在敌方地面单位，则自身【命中】与【贯通】提升16%，持续2回合，不可叠加。下回合主动攻击后，对攻击范围内离自身最近的1格内地面目标发动1次追击。', 1, 3, 0, 0),
  ('ARM111701', '职能', 7, 'SJ0722', '徐进弹幕', '对所有【被标记】地面敌方单位发动1次攻击。自身攻击前，自身【对地火力】提升15%，本次攻击有效。', 1, 3, 75, 1),
