  ('ARM114202', '其他', 0, 'AS1236', '临时工', '作战开始时，自身【暴击概率】【暴击伤害】永久提升60%。每次自身行动后，若本回合施放过攻击或警戒技能，【暴击概率】【暴击伤害】永久降低25%（最多降低50%，不可抵抗、不可驱散）。', 0, 0, 0, 3),
  ('ARM114202', '职能', 5, 'SJ0521', '隐匿埋伏', '清除自身所有【标记】，自身【暴击概率】提升28%，【存在感】降低2点，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 0),
  ('ARM114202', '职能', 5, 'SJ0522', '隐匿狙击', '攻击前方1个【被标记】敌人，本次攻击【对地火力】提升30%，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 2, 3, 100, 1),
  ('ARM114202', '职能', 5, 'SJ0523', '坚守警戒', '本回合内，对自身前方地面1-4格范围内所有移动过的敌人发动警戒攻击，若敌方目标【被标记】，则攻击前自身【对地火力】提升24%，本次警戒攻击有效。', 2, 5, 0, 2),
  ('ARM114202', '职能', 5, 'SJ0524', '移动射击', '攻击前方地面1-1格范围内1个敌人1次，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 1, 0, 100, 3),
  ('ARM114202', '职能', 4, 'SJ0421', '近距射击', '攻击前方1-1格范围内1个敌人1次，若目标【被标记】，本次攻击【对地火力】提升30%。', 1, 0, 100, 0),
  ('ARM114202', '职能', 4, 'SJ0422', '破阵猛击', '攻击前方2-3格范围内1个敌人，并赋予目标【破阵】状态，若目标【被标记】，可发动追击。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 2, 5, 100, 1),
