  ('ARM114402', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM114402', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM114402', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM114701', '其他', 0, 'SS114701', '林中小车', '攻击前方1-2格范围内的1个地面目标，攻击前若自身处于【隐匿】状态，则本回合【暴击概率】提升20%且50%概率发动1次追击。', 1, 3, 100, 0),
  ('ARM114701', '其他', 0, 'DOL1147', '永不灭亡', '自身受主动攻击而【减员】后，本回合自身【机动】提升70%，【幸运】提升300点。自身行动前，若「7TP」在场，则自身前方1-2格范围内每存在1个敌方地面单位，本回合自身【对地火力】和【贯通】提升10%，最高可提升40%。', 0, 0, 0, 1),
  ('ARM114701', '其他', 0, 'AS1141', '轻装上阵', '作战开始时，自身【装甲】永久降低20%。我方阶段开始时，若自身处于移动形态，则本回合自身【机动】提升8%；若自身处于固守形态，则本回合自身【对地火力】提升8%。', 0, 0, 0, 2),
  ('ARM114701', '其他', 0, 'AS3051', '信号旗', '我方阶段开始时，同格我方所有轻型和中型地面单位本回合【机动】提升8%，重型单位本回合【暴击伤害】提升8%，不可叠加。', 0, 0, 0, 3),
