  ('ARM115302', '其他', 0, 'DOL1153', '奇门遁甲', '我方阶段开始时，若本回合自身前进过，则获得【被草淹没】状态——【存在感】降低2点、【暴击概率】提升16%，持续1回合。主动攻击后，清除自身【被草淹没】状态。', 0, 0, 0, 1),
  ('ARM115302', '其他', 0, 'AS1022', '集群效益（陆）·改', '主动攻击地面目标时，若自身【成员数】＞2，则自身【对地火力】提升8%；若自身【成员数】＞5，则【对地火力】额外提升3%；若自身【成员数】＞7，则【对地火力】再额外提升4%。', 0, 0, 0, 2),
  ('ARM115302', '其他', 0, 'AS2020', '狙击支援·改', '主动攻击时，若身后存在至少1个我方重型歼击车单位，则本次攻击【对地火力】提升15%。', 0, 0, 0, 3),
  ('ARM115302', '职能', 5, 'SJ0521', '隐匿埋伏', '清除自身所有【标记】，自身【暴击概率】提升28%，【存在感】降低2点，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 0),
  ('ARM115302', '职能', 5, 'SJ0522', '隐匿狙击', '攻击前方1个【被标记】敌人，本次攻击【对地火力】提升30%，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 2, 3, 100, 1),
  ('ARM115302', '职能', 5, 'SJ0523', '坚守警戒', '本回合内，对自身前方地面1-4格范围内所有移动过的敌人发动警戒攻击，若敌方目标【被标记】，则攻击前自身【对地火力】提升24%，本次警戒攻击有效。', 2, 5, 0, 2),
  ('ARM115302', '职能', 5, 'SJ0524', '移动射击', '攻击前方地面1-1格范围内1个敌人1次，若自身处于【隐匿】状态，本次攻击【暴击概率】提升28%；若目标带有【破阵】，本次【暴击伤害】提升33%。', 1, 0, 100, 3),
  ('ARM115302', '职能', 6, 'SJ0622', '机动支援', '自身进入固守形态，攻击自身前方地面1-2的1个敌人1次，并【标记】目标，持续3回合。', 2, 3, 100, 0),
  ('ARM115302', '职能', 6, 'SJ0623', '火力支援', '攻击前方1个地面【被标记】的敌人，并【标记】自身2回合。自身攻击前，自身【对地火力】提升30%，本次攻击有效。', 2, 3, 100, 1),
  ('ARM115302', '职能', 6, 'SJ0624', '火力掩护', '本回合可对前方1-4格范围内所有主动攻击过的敌人发动反击。', 2, 5, 0, 2),
  ('ARM115401', '其他', 0, 'SS115401', '全向观察', '赋予前方第2格范围内所有敌方地面单位特殊标记【威吓】，本阶段有效。我方单位主动攻击带有【威吓】的目标后，迫使目标后退1格。', 1, 5, 0, 0),
  ('ARM115401', '其他', 0, 'DOL1154', '一息尚存', '我方阶段开始时，若自身【成员数】低于67%且不低于34%，则本回合自身【对地火力】提升80%；若低于34%，则本回合自身【对地火力】提升260%。自身行动前，若「TKS」在场，则自身前方1-2格范围内，每存在1个敌方地面单位，本回合自身【装甲】和【暴击伤害】提升10%，最高可提升30%。', 0, 0, 0, 1),
  ('ARM115401', '其他', 0, 'AS1023', '近程防御（机动）', '受主动攻击时，若与自身前方的攻击者距离＜3格，则自身【机动】提升5%。', 0, 0, 0, 2),
  ('ARM115401', '其他', 0, 'AS3013', '轻装集群（坦克）', '我方阶段开始时，若同格存在≥2个我方轻型坦克单位，则本回合同格所有我方轻型坦克【暴击概率】提升6%，不可叠加。', 0, 0, 0, 3),
  ('ARM115401', '职能', 1, 'SJ0121', '游击侦察', '攻击自身前方地面1-2格范围内1个敌人并【标记】，持续3回合。攻击后自身后退1格。', 2, 0, 100, 0),
  ('ARM115401', '职能', 1, 'SJ0122', '隐匿', '使自身进入固守形态，清除自身所有【标记】，自身【存在感】降低2点，【暴击概率】提升28%，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 1),
  ('ARM115401', '职能', 1, 'SJ0123', '定点侦察', '敌方阶段时，自身前方地面1-4格范围内敌人在攻击前将会赋予【被标记】，持续3回合，且其【命中补正】降低20%，持续1回合。', 2, 5, 0, 2),
