  ('ARM116202', '职能', 9, 'SJ0923', '防空阵地', '赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，并攻击所有【被标记】敌方空中单位。本次攻击自身【对空火力】提升30%。若自身处于【阵地】状态时被【标记】，则自身【对地火力】、【对空火力】提升30%，持续3回合，不可叠加。', 2, 3, 75, 2),
  ('ARM116202', '职能', 9, 'SJ0924', '平射阵地', '赋予自身【阵地】状态，清除大部分负面状态，但无法免疫【标记】及特定不利效果，并攻击自身前方2-3格范围内1个敌方地面单位。自身攻击前，若目标【被标记】，则自身【对地火力】提升30%，本次攻击有效。若自身处于【阵地】状态时被【标记】，则自身【对地火力】、【对空火力】提升30%，持续3回合，不可叠加。', 2, 1, 100, 3),
  ('ARM116301', '其他', 0, 'SS116301', '点数射击', '攻击前方1-3格1个敌方地面单位，攻击后若我方剩余【CP】＞4点则发动1次追击，若＞8点则再发动1次追击。', 2, 5, 100, 0),
