  ('ARM117402', '其他', 0, 'DOL1174', '装甲兔女郎', '自身【装甲】永久提升20%。我方阶段开始时，【标记】前方1~3格1个敌方地面单位，持续1回合，整场战斗可生效1次。我方单位被敌方地面单位主动攻击后，若「安妮莉丝」与攻击者距离≤3，则【标记】攻击者，持续1回合。', 0, 0, 0, 1),
  ('ARM117402', '其他', 0, 'AS3036', '黑桃分队', '我方黑十字地面单位施放技能前，根据该单位正面状态数量提升其【暴击概率】（最高可提升120%），本回合有效；且其攻击时溢出的【暴击概率】按2：1转化为【暴击伤害】（上限50%）。', 0, 0, 0, 2),
  ('ARM117402', '其他', 0, 'AS3038', '派彩', '作战开始时，每个我方黑十字坦克获得1点【CP】，且【机动】永久提升20%（不可叠加）。', 0, 0, 0, 3),
  ('ARM117402', '职能', 2, 'SJ0221', '破阵冲锋', '攻击前方2-2格范围内1个敌人，攻击后赋予目标【破阵】状态。攻击后自身【装甲】提升15%，持续2回合。攻击后自身前进1格。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 0, 100, 0),
  ('ARM117402', '职能', 2, 'SJ0222', '推进白刃', '对前方1-2格范围内1个敌人发动白刃战。若目标带有【破阵】效果，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束，不可叠加。自身前进2格。', 1, 5, 100, 1),
  ('ARM117402', '职能', 2, 'SJ0223', '破阵射击', '攻击前方1-2格范围内1个敌人，本次攻击中、重型单位会额外提升自身【对地火力】25%，攻击后赋予目标【破阵】。若目标【被标记】，本次攻击【对地火力】提升30%。若目标已经处于【破阵】状态，则自身攻击前目标的【装甲】和【机动】下降18%，持续至【破阵】结束。处于【破阵】状态的单位负面状态生效率提升100%。', 1, 5, 100, 2),
  ('ARM117402', '职能', 2, 'SJ0224', '突袭白刃', '对前方1-1格范围内所有敌人依次进行白刃战。若目标已经处于【破阵】状态，则自身攻击前目标的装甲和机动下降18%，持续至【破阵】结束，不可叠加。白刃结束后，自身切换为移动形态。', 1, 8, 100, 3),
  ('ARM117402', '职能', 1, 'SJ0121', '游击侦察', '攻击自身前方地面1-2格范围内1个敌人并【标记】，持续3回合。攻击后自身后退1格。', 2, 0, 100, 0),
  ('ARM117402', '职能', 1, 'SJ0122', '隐匿', '使自身进入固守形态，清除自身所有【标记】，自身【存在感】降低2点，【暴击概率】提升28%，持续2回合，不可叠加。赋予自身【隐匿Ⅰ】状态，持续永久。隐匿Ⅰ：①广域攻击技能的目标中处于【隐匿Ⅰ】状态且【存在感】不是最高的目标不会受到攻击伤害；②【隐匿Ⅰ】和【标记】互不共存；③单位主动攻击后会清除自身【隐匿Ⅰ】。', 1, 3, 0, 1),
