-- 技能表 arms_skills：机体 → 技能（名称 + 描述 + AP/CP/伤害）。
-- 归属 other = 专属/DOLLS/改造技能合并（页面不区分类型）；job = 职能技能，按职能分开存。
-- 描述取站点 skill_info() 口径：同一 skillid 取 skillLevel 最高的那条。
-- 用法：psql -d armsbank_db -U postgres -f setup_arms_skills.sql

BEGIN;
SET client_encoding = 'UTF8';

DROP TABLE IF EXISTS arms_skills;
CREATE TABLE arms_skills (
  armsid      text    NOT NULL,
  kind        text    NOT NULL,   -- 'other' | 'job'
  jobid       integer NOT NULL DEFAULT 0,
  skillid     text    NOT NULL,
  name        text    NOT NULL,
  description text    NOT NULL DEFAULT '',
  ap          integer NOT NULL DEFAULT 0,
  cp          integer NOT NULL DEFAULT 0,
  damage      integer NOT NULL DEFAULT 0,
  seq         integer NOT NULL DEFAULT 0,
  PRIMARY KEY (armsid, kind, jobid, skillid)
);


COMMIT;
